"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7257],{1028(e){e.exports=JSON.parse('{"title":"Tanstack Query \ucffc\ub9ac \ubb34\ud6a8\ud654 \ucd94\uc0c1\ud654","date":"2024-06-05","coverUrl":null,"html":"<h2 data-notion-block-id=\\"ae718169-2e0a-40ae-b6d1-39181a4534f2\\" id=\\"ae718169-2e0a-40ae-b6d1-39181a4534f2\\">Tanstack Query \ucffc\ub9ac \ubb34\ud6a8\ud654 \ucd94\uc0c1\ud654</h2><a href=\\"https://tkdodo.eu/blog/automatic-query-invalidation-after-mutations\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/automatic-query-invalidation-after-mutations</a><p data-notion-block-id=\\"3be722a4-a961-4d88-b6ee-08d5399d09fb\\"><b>\uc2ec\uc724\uc12d</b>: Tanstack Query\uc5d0\uc11c Mutation \uc774\ud6c4 Query Invalidation \uc790\ub3d9\ud654\ub97c \ucd94\uc0c1\ud654\ud558\ub294 \uacfc\uc815\uc744 \ud1b5\ud574 Tanstack Query\uc5d0 \uae30\ubcf8\uac12\uc73c\ub85c Mutation \uc774\ud6c4 Query Invalidation \uc790\ub3d9\ud654\ub97c \uad6c\ud604\ud558\ub294 \uac83\uc740 \uc27d\uc9c0\ub9cc \ubaa8\ub4e0 \uc0c1\ud669\uc744 \ub300\uc751\ud558\ub3c4\ub85d \ucd94\uc0c1\ud654\ud558\ub294 \uac83\uc740 \uc5b4\ub835\ub2e4\ub294 \uac83\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4. \uadf8\ub9ac\uace0 invalidateQueries\uc640 callback\uc5d0 \ub300\ud55c\uac83\ub3c4\uc694!</p><h2 data-notion-block-id=\\"bd09632a-7805-48c6-a538-fde6442ffd02\\" id=\\"bd09632a-7805-48c6-a538-fde6442ffd02\\">RSC\uc758 \ud568\uc815</h2><a href=\\"https://frontendmasters.com/blog/combining-react-server-components-with-react-query-for-easy-data-management/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/combining-react-server-components-with-react-query-for-easy-data-management/</a><p data-notion-block-id=\\"d8723722-6382-47bb-9e9d-5075dd1d748e\\"><b>\uc2ec\uc724\uc12d</b>: \uc800\uc790\ub294 Next.js\uc758 RSC \uad6c\ud604\uc5d0\uc11c \uce90\uc2dc \ub3d9\uc791\uc774 \uc774\uc0c1\ud558\ub2e4\ub294 \uac83\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4(\uadf8\ub9ac\uace0 Server Action\uc774 \uc21c\ucc28\uc801\uc73c\ub85c\ub9cc \ub3d9\uc791\ud55c\ub2e4\ub294 \uac83\ub3c4\uc694 - \ubb3c\ub860 <a href=\\"https://react.dev/reference/rsc/use-server#caveats\\">\uc758\ub3c4\ub41c \ub3d9\uc791</a>\uc774\ub77c\uace0\ub294 \ud558\ub124\uc694). \uadf8\ub9ac\uace0 \uadf8\uc758 \ub300\uc548\uc73c\ub85c \ud074\ub77c\uc774\uc5b8\ud2b8\uc758 <code>@tanstack/query</code>\uc640 <code>@tanstack/react-query-next-experimental</code>\uc744 \ucd94\ucc9c\ud569\ub2c8\ub2e4. \ubc88\ub4e4 \uc0ac\uc774\uc988\uac00 \ub298\uc5b4\ub098\ub3c4 UX\uac00 \uac15\ud654\ub418\ub294 \uc774\uc810\uc744 \uac15\uc870\ud558\uba74\uc11c\uc694. \uc774\uc804\uc5d0 <a href=\\"https://ones-to-watch.ethansup.net/news/post/bafbcbbf-9100-45c9-b683-a1a5134930fa\\">Next.js App Router\ub294 \uc2dc\uae30\uc0c1\uc870\ub2e4</a> \uae00\uc744 \uc77d\uc5c8\uc744 \ub54c\uc640 \ube44\uc2b7\ud558\uac8c Next.js\uc758 \ub9ce\uc740 \uacf3\uc5d0\uc11c \ub3d9\uc791\uc774 \uc798 \ub418\uc9c0 \uc54a\uc544 \ubcf4\uc5ec\uc11c \uc544\uc27d\ub124\uc694.</p><h2 data-notion-block-id=\\"c6a20aa3-4844-479b-bcfb-6abace7c64d9\\" id=\\"c6a20aa3-4844-479b-bcfb-6abace7c64d9\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \ud68c\uace0</h2><a href=\\"https://kyleshevlin.com/design-system-retrospective/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kyleshevlin.com/design-system-retrospective/</a><p data-notion-block-id=\\"8ebb7be8-4423-4269-ad78-25c03de0359d\\"><b>\uc2ec\uc724\uc12d</b>: \uc800\uc790\uac00 \ud55c \ud68c\uc0ac\uc758 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4e4\uac8c \ub418\uba74\uc11c, Chakra UI\uc640 \ube44\uc2b7\ud55c \ud569\uc131 \ucef4\ud3ec\ub10c\ud2b8 \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub294\ub370, \uc2e4\ud328\ud55c \uacbd\ud5d8\uc744 \ud68c\uace0\ud55c \uae00\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uac00\uc838\uc628 <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#db3ef69e-93d7-422a-a3e0-d5816a79be50\\">\uc9c4\ud654\ud558\ub294 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c</a>\uc5d0\ub3c4 \ubcf4\uc600\ub4ef\uc774, \uc5ec\ub7ec\uac00\uc9c0 \uc811\uadfc \ubc29\uc2dd\uc774 \uc788\uace0, \ud68c\uc0ac\uc5d0\uc11c \uc120\ud638\ud558\ub294 \ubc29\uc2dd\uc5d0 \ub9de\uac8c \uad6c\ud604\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc801\ub2f9\ud55c \ub0b4\ubd80 \uac1c\ubc1c\uc790\ub97c \uc0c1\ub300\ub85c \ud55c \ub9c8\ucf00\ud305\uacfc \ubb38\uc11c\ud654\ub3c4\uc694.</p><h2 data-notion-block-id=\\"07099ebc-2b97-45b4-9f1c-83a0dcf4935f\\" id=\\"07099ebc-2b97-45b4-9f1c-83a0dcf4935f\\">React Aria\uc758 \uc7a5\ub2e8\uc810</h2><a href=\\"https://argos-ci.com/blog/react-aria-migration\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://argos-ci.com/blog/react-aria-migration</a><p data-notion-block-id=\\"9bccb58e-3400-4c42-b51c-143dcf1c104c\\"><b>\uc2ec\uc724\uc12d</b>: React Aria\uc758 \ub2e4\uc591\ud55c \ubc29\uc2dd(<a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#db3ef69e-93d7-422a-a3e0-d5816a79be50\\">\uc9c4\ud654\ud558\ub294 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c</a>\uacfc \uac19\uc774 React spectrum / React Aria - React Stately\ub85c \uc81c\uacf5\uc911\uc785\ub2c8\ub2e4.)\uc73c\ub85c \uc811\uadfc\uc131 \uc88b\uc740 \ucef4\ud3ec\ub10c\ud2b8\ub97c \uc81c\uacf5\ud558\ub294 \uac83\uc740 \ub9e4\uc6b0 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc800\uc790\ub3c4 \uadf8\ub807\uac8c \uc0dd\uac01\ud558\uc5ec UI \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c React Aria\ub85c \ubc14\uafb8\uae30\ub85c \uacb0\uc815\ud558\uc600\uace0, \uc9c4\ud589\ud558\uba74\uc11c \uacaa\uc740 \uc7a5\ub2e8\uc810\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc800\ub3c4 UI \ubc29\uc2dd\uc744 React Aria\uc2dd\uc73c\ub85c \ubcc0\uacbd\ud574\uc57c \ud558\uc9c0\ub9cc, \uc218\ub9ce\uc740 \uc811\uadfc\uc131\uc744 \ub300\uc2e0 \ub9cc\ub4e4\uc5b4\uc900\ub2e4\ub294 \uc810\uc5d0\uc11c \uc88b\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ubb38\uc11c\ud654\ub3c4 \uaf64 \uc798 \ub418\uc5b4\uc788\uad6c\uc694.</p><h2 data-notion-block-id=\\"74f4eb91-3e62-42f4-a1e1-4e4d6ad3375c\\" id=\\"74f4eb91-3e62-42f4-a1e1-4e4d6ad3375c\\">GraphQL\uc740 \uc815\ub9d0 \uc4f0\ub808\uae30\uc778\uac00\uc694?</h2><a href=\\"https://graphql.org/conf/2023/sessions/de1472b4294ac91745f3648d9228d8f2/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://graphql.org/conf/2023/sessions/de1472b4294ac91745f3648d9228d8f2/</a><p data-notion-block-id=\\"c4190a58-233b-4736-9623-0decc62ebf43\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://bessey.dev/blog/2024/05/24/why-im-over-graphql/\\">6\ub144\ub3d9\uc548 GraphQL\uc744 \uc368\ubcf4\uace0 GraphQL\ub97c \ubc84\ub9b0 \uc774\uc720</a>\ub97c \ubcf4\uace0 \uc0dd\uac01\uc774 \ub4e4\uc5b4\uc11c GraphQL\uc758 \ub3c4\uc785\uc774 \ub514\uc790\uc774\ub108\uc640 PM\uc5d0\uac8c \uc5b4\ub5a0\ud55c \uc88b\uc740 \uc810\uc744 \uac00\uc9c0\ub294\uc9c0 \ubc1c\ud45c\ud55c \uc601\uc0c1\uc744 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uc0ac\uc2e4 \uc774\uc804\uc5d0 \uac00\uc838\uc628 <a href=\\"https://ones-to-watch.ethansup.net/news/post/7a30f3669a2840449643c6c7f14270d8\\">\ub2f9\uc2e0\uc740 GraphQL\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4</a>\uac00 \ub354 \ub113\uc740 \uc2dc\uc57c\ub97c \uac00\uc9c8 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \uae00\uc778 \uac83 \uac19\uc9c0\ub9cc.. \uc774\ubbf8 \uac00\uc838\uc654\uc73c\ub2c8\uae4c\uc694 :) Database\uc5d0\uc11c \uc9c1\uc811 GraphQL API\ub97c \ub9cc\ub4dc\ub294 Hasura, GraphQL \uad00\ub828\ub41c \ud234\uc744 \uc81c\uacf5\ud558\ub294 Apollo\uc640 The Guild, \ubcf4\uc548\uc744 \uc81c\uacf5\ud558\ub294 Escape(<a href=\\"https://escape.tech/academy/\\">GraphQL \ubcf4\uc548\uc744 \uc54c\ub824\uc8fc\ub294 \uc0ac\uc774\ud2b8</a>\ub3c4 \ub9cc\ub4e4\uc5c8\ub124\uc694!)\u2026 \uc5ec\ub7ec \ud234\uc774 \ub9ce\uc73c\ub2c8 \uc790\uc2e0\uc5d0\uac8c \ub9de\ub294 \ud234\uc744 \uc54c\ub9de\uac8c \uc4f0\ub294\uac8c \uc911\uc694\ud558\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"969cfc7b-5f89-42de-896d-eacff8b32799\\" id=\\"969cfc7b-5f89-42de-896d-eacff8b32799\\">React\uc5d0\uc11c\uc758 \uba54\ubaa8\ub9ac \ub204\uc218</h2><a href=\\"https://schiener.io/2024-03-03/react-closures\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://schiener.io/2024-03-03/react-closures</a><p data-notion-block-id=\\"a00e188a-5a9d-4f55-b915-40712c906dc9\\"><b>\uc2ec\uc724\uc12d</b>: memoization\uc5d0\uc11c Closure\uc73c\ub85c \ub450\uac1c\uc758 \ud568\uc218 \uc678\ubd80 \ubcc0\uc218\ub97c \uac00\uc84c\uc744 \uacbd\uc6b0 \ubc1c\uc0dd\ud558\ub294 \uba54\ubaa8\ub9ac \ub204\uc218\ub97c \uc124\uba85\ud55c \uc601\uc0c1\uc785\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc0c1\ud669(\ub450 \uac1c \uc774\uc0c1 \uc678\ubd80 \ud568\uc218\ub97c \ud55c \uacf3\uc5d0\uc11c memoization\ud558\ub294 \uc0c1\ud669)\uc744 \ub9ce\uc774 \ub9c8\uc8fc\uce58\uc9c4 \uc54a\uaca0\uc9c0\ub9cc \uc774\ub97c \uc704\ud574 <a href=\\"https://ko.javascript.info/closure\\">\ubcc0\uc218\uc758 \uc720\ud6a8\ubc94\uc704\uc640 \ud074\ub85c\uc800</a> \ubb38\uc11c\ub97c \ud1b5\ud574 \ud074\ub85c\uc800\uc5d0 \ub300\ud574 \uc54c\uc544\ub458 \ud544\uc694\ub294 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"8b2611a5-2c03-46e9-b023-1a903533615a\\" id=\\"8b2611a5-2c03-46e9-b023-1a903533615a\\">Real World \uc131\ub2a5 \ucd5c\uc801\ud654</h2><a href=\\"https://www.iamtk.co/optimizing-inp-for-a-react-app-and-performance-learnings\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.iamtk.co/optimizing-inp-for-a-react-app-and-performance-learnings</a><p data-notion-block-id=\\"18cab4a2-e059-4928-b169-f26be98245a9\\"><b>\uc2ec\uc724\uc12d</b>: \uc131\ub2a5 \ucd5c\uc801\ud654\ud558\ub294 \uad6c\uccb4\uc801\uc778 \uc608\uc2dc\ub97c \uc801\uc5b4\ub0b8 \uae00\uc785\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uac00\uc7a5 \uac15\uc870\ud574\ub3c4 \uc9c0\ub098\uce58\uc9c0 \uc54a\uc740 \uac83\uc740 \uc0c1\ud0dc\ub97c \ucd5c\ub300\ud55c \uc801\uac8c \uad00\ub9ac\ud558\uace0, \uc2dc\uac04\uc774 \uc624\ub798 \uac78\ub9ac\ub294 \uc791\uc5c5\uc774 \uc788\ub2e4\uba74, \ub80c\ub354\ub9c1\uc744 \ub9c9\uc9c0 \uc54a\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc8fc\uc138\uc694.</p><h2 data-notion-block-id=\\"de888686-3d72-4003-8a20-e36af601960c\\" id=\\"de888686-3d72-4003-8a20-e36af601960c\\">\ub2e8\uace8\uba74\uc811: \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc8fc\uc18c\ub97c \uc785\ub825\ud558\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc77c\uc5b4\ub098\ub098\uc694?</h2><a href=\\"https://devonperoutky.super.site/blog-posts/mediocre-engineers-guide-to-https\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devonperoutky.super.site/blog-posts/mediocre-engineers-guide-to-https</a><p data-notion-block-id=\\"be73fed9-4ead-4dc2-97bd-ef3ccb46221f\\">\uc2e0\uc785\uc5d0\uac8c \ubb3c\uc5b4\ubcf4\ub294 \ub2e8\uace8 \uc9c8\ubb38\uc778 \\"\ube0c\ub77c\uc6b0\uc800\uc5d0 \uc8fc\uc18c\ub97c \uc785\ub825\ud558\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc77c\uc5b4\ub098\uc694?\\"\ub97c HTTP \ud30c\ud2b8\uc5d0\uc11c \uae4a\uac8c \ud30c\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uad6c\uc870\uc5d0 \ub300\ud55c \ud30c\uc545\uacfc \ub354\ubd88\uc5b4\uc11c \ucd5c\uc2e0 \ubc84\uc804\uc778 TLS 1.3\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uc9c0\ub3c4 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f2bcbd5c-166a-41c4-b8f2-c765de5ab298\\" id=\\"f2bcbd5c-166a-41c4-b8f2-c765de5ab298\\"><code>&#x3C;script></code> \ud0dc\uadf8\uc758 \ub3d9\uc791 \ubc29\uc2dd</h2><a href=\\"https://webdeveloper.beehiiv.com/p/html-script-element-attributes-async-vs-defer-vs-typemodule\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webdeveloper.beehiiv.com/p/html-script-element-attributes-async-vs-defer-vs-typemodule</a><p data-notion-block-id=\\"6887222d-9a86-4e68-a6d5-47405202ee71\\"><code>&#x3C;script></code> \ud0dc\uadf8\uc5d0\uc11c <code>type=\\"module\\"</code>\uc774 \ucd94\uac00\ub418\uc5c8\uc744 \ub54c \ub3d9\uc791\uc774 \uc5b4\ub5bb\uac8c \ubc14\ub00c\ub294\uc9c0 \uc124\uba85\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"a980d441-0568-492a-aa16-0d90310cf0d6\\" id=\\"a980d441-0568-492a-aa16-0d90310cf0d6\\">200\uc904\ub85c Virtual DOM \uad6c\ud604\ud558\uae30</h2><a href=\\"https://lazamar.github.io/virtual-dom/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lazamar.github.io/virtual-dom/</a><p data-notion-block-id=\\"381f532a-7a19-4864-a831-310f2787f6e2\\">React\uac19\uc740 Virtual DOM\uc758 \uac1c\ub150\uc744 \uc774\ud574\ud558\uae30\uc5d0 \uc88b\uc740 Virtual DOM \uad6c\ud604\uae30\uc785\ub2c8\ub2e4. \uac04\ub2e8\ud558\uac8c \uc774\ud574\ud558\uae30 \uc88b\uac8c \uad6c\uc131\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"ccb52d39-e6f9-4680-807e-c56f6ec851b3\\" id=\\"ccb52d39-e6f9-4680-807e-c56f6ec851b3\\">\ubc18\uc751\ud615 \uc6f9 \ube0c\ub77c\uc6b0\uc800 \ud14c\uc2a4\ud2b8 \ud301</h2><a href=\\"https://www.jenchan.biz/blog/stop-resizing-your-browser-improve-responsive-testing\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jenchan.biz/blog/stop-resizing-your-browser-improve-responsive-testing</a><p data-notion-block-id=\\"776fa8f6-4eb6-47b7-9535-a26fb48af259\\">\uac04\ub2e8\ud55c \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ubc18\uc751\ud615 \uc6f9\uc744 \ud14c\uc2a4\ud2b8\ud558\ub294 \ud301\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"70abc794-b4c1-4d3e-8c01-fb60f6b76068\\" id=\\"70abc794-b4c1-4d3e-8c01-fb60f6b76068\\">Next.js 15 RC</h2><a href=\\"https://nextjs.org/blog/next-15-rc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/next-15-rc</a><p data-notion-block-id=\\"abba4932-4b95-43b4-a16e-c7346f1acc44\\">Next.js\uc5d0\uc11c 15 \ucd9c\uc2dc \uc804 \ubc84\uc804\uc744 \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4. React \uc2e0 \uae30\ub2a5\uc5d0 \ub300\ud55c \uc9c0\uc6d0\uacfc \ubd80\ubd84 \ud504\ub9ac\ub80c\ub354\ub9c1\u2026 \uc5ec\ub7ec \uae30\ub2a5\uc5d0 \ub300\ud55c \uc18c\uac1c\ud569\ub2c8\ub2e4. RSC\uc758 \ud568\uc815 \uae30\uc0ac\uc5d0\ub3c4 \ub098\uc654\ub4ef\uc774 \uce90\uc2dc API\uc640 \uae30\ubcf8\uac12\uc744 \ubc14\uafbc\ub2e4\uace0 \ud558\ub2c8 \uc54c\uc544\ub450\uba74 \uc88b\uc2b5\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"40711796-00d7-43e8-b52a-1f0b0f9d4cae\\" id=\\"40711796-00d7-43e8-b52a-1f0b0f9d4cae\\">Partial Prerendering \uad6c\ud604\ud558\uae30</h2><a href=\\"https://developers.netlify.com/guides/partial-prerendering-without-a-framework/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developers.netlify.com/guides/partial-prerendering-without-a-framework/</a><p data-notion-block-id=\\"3ac0ca3f-ef16-474f-be85-98aee3235b23\\">\uc704\uc5d0\uc11c \ub098\uc628 \uc2e0\uae30\ub2a5\uc778 Partial Prerendering\uc744 \uc21c\uc218 JS\ub85c \uad6c\ud604\ud558\ub294 \uacfc\uc815\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p>"}')}}]);